/**
 * The element x modality grid on screen (#511): the drawing the exported chart sheet has always carried, as a view
 * of its own. Decoration over the table beside it, which holds every value as text.
 */
/**
 * @module ui/EmphasisGrid
 * @purpose Draws the chart's element x modality grid with `renderEmphasisGridSvg`, the same drawing the sheet export uses.
 * @conventions Hidden from assistive tech like the wheel: the Elements & modalities table under it is the accessible equivalent. The drawing is generated by this app from computed data, never user-supplied markup.
 * @exports EmphasisGrid
 */
import { formatFixed } from './format.js';
import { useMemo } from 'react';
import { renderEmphasisGridSvg, type EmphasisGridInput } from '../chart/emphasis-grid.js';
import { resolveSheetGeometry } from '../chart/sheet-geometry.js';

/** The drawing's width in its own units, shown 1:1 (CSS caps its width here) so its text is as large as the page's. */
const GRID_WIDTH = 560;

export function EmphasisGrid({ input }: { readonly input: EmphasisGridInput }): React.JSX.Element {
  const svg = useMemo(() => {
    const fontSize = resolveSheetGeometry(GRID_WIDTH).panelFontSize;
    const { markup, height } = renderEmphasisGridSvg(input, { x: 0, y: 0, width: GRID_WIDTH }, fontSize);
    return (
      `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${String(GRID_WIDTH)} ${formatFixed(height, 2)}" ` +
      `class="chart-sheet chart-emphasis-grid">${markup}</svg>`
    );
  }, [input]);
  return (
    <div
      className="chart-matrix-view chart-emphasis-view"
      aria-hidden="true"
      dangerouslySetInnerHTML={{ __html: svg }}
    />
  );
}
